import json
import re
import datetime
try:
    verified = vars.get('security_route') == 'verified'
    vars['validation_route'] = 'collection' if verified else 'identity'
    vars['validation_message'] = ''
    holidays = set(['2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01'])
    now = datetime.datetime.fromisoformat(str(vars.get('now','')).replace('Z','+00:00'))
    today = now.date()
    def business(d):
        return d.weekday() < 5 and d.isoformat() not in holidays
    def next_business(d):
        d += datetime.timedelta(days=1)
        while not business(d):
            d += datetime.timedelta(days=1)
        return d
    def decoded(value, fallback):
        if isinstance(value,str):
            try:
                value = json.loads(value)
            except Exception:
                return fallback
        return value if isinstance(value,type(fallback)) else fallback
    def parse_day(raw, birth=False):
        text = str(raw).strip().lower().replace(',','')
        text = re.sub(r'(\d)(st|nd|rd|th)\b',r'\1',text)
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}',text):
            return datetime.date.fromisoformat(text)
        numeric = re.fullmatch(r'(\d{1,2})[ /.-](\d{1,2})[ /.-](\d{4})',text)
        if numeric:
            return datetime.date(int(numeric.group(3)),int(numeric.group(2)),int(numeric.group(1)))
        months = ['january','february','march','april','may','june','july','august','september','october','november','december']
        tokens = text.split()
        for index, month in enumerate(months,1):
            for token in tokens:
                if token == month or token == month[:3]:
                    numbers = re.findall(r'\b\d+\b',text)
                    if len(numbers) == 2 and len(numbers[1]) == 4:
                        return datetime.date(int(numbers[1]),index,int(numbers[0]))
                    if len(numbers) == 1 and not birth:
                        return datetime.date(today.year,index,int(numbers[0]))
        if not birth:
            if text == 'today':
                return today
            if text == 'tomorrow':
                return today + datetime.timedelta(days=1)
            weekdays = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday']
            for index, weekday in enumerate(weekdays):
                if text in ['this ' + weekday,'next ' + weekday]:
                    monday = today - datetime.timedelta(days=today.weekday())
                    return monday + datetime.timedelta(days=index + (7 if text.startswith('next ') else 0))
        return False
    def phone_digits(parts):
        text = ' '.join(str(x) for x in parts).lower()
        words = dict(zero='0',oh='0',one='1',two='2',three='3',four='4',five='5',six='6',seven='7',eight='8',nine='9')
        for word, digit in words.items():
            text = re.sub(r'\b' + word + r'\b',digit,text)
        text = re.sub(r'[\s,-]','',text)
        return text
    if not verified:
        event = decoded(vars.get('identity_event',''),dict())
        vars['identity_event'] = ''
        vars['security_input_state'] = 'missing'
        vars['identity_instruction'] = 'Ask only for the missing part of the current answer.'
        if event.get('kind') == 'security':
            field = str(event.get('field',''))
            expected = 'phone_last4' if vars.get('dob_pass') == 'yes' else 'date_of_birth'
            parts = event.get('parts',[])
            if not isinstance(parts,list):
                parts = [str(parts)]
            raw = ' '.join(str(x) for x in parts).strip()
            answer = ''
            if field != expected or int(vars.get('wrong_answer_count',0)) >= 3:
                vars['identity_instruction'] = 'Do not validate out of order or after the security limit.'
            elif field == 'phone_last4':
                answer = phone_digits(parts)
                if not re.fullmatch(r'\d{4}',answer):
                    answer = ''
                    vars['identity_instruction'] = 'The phone answer is incomplete or ambiguous. Ask only for the missing digits; preserve the supplied leading zeroes.'
            else:
                if vars.get('dob_hint_pending') == 'yes' and not re.search(r'[A-Za-z]',raw):
                    vars['identity_instruction'] = 'Ask the customer to say the month as a word. Do not guess or swap it yourself.'
                else:
                    try:
                        date = parse_day(raw,True)
                    except Exception:
                        date = False
                    if date:
                        answer = date.isoformat()
                    else:
                        vars['identity_instruction'] = 'Ask only for the missing or unclear birth-date component, including the full year. Numeric dates mean day, month, year.'
            if answer and field == expected:
                vars['validated_security_field'] = field
                vars['validated_security_answer'] = answer
                vars['security_input_state'] = 'ready'
                vars['identity_instruction'] = 'Immediately call verify_identity with the validated field and answer. Do not infer that it passed.'
        elif event.get('kind') == 'callback':
            next_day = next_business(today)
            vars['callback_facts'] = json.dumps(dict(today=today.isoformat(), next_business_day=next_day.isoformat(), earliest_time='10:00', latest_time='19:00', strictly_after=now.isoformat()))
            try:
                day = parse_day(event.get('date',''))
                raw_time = str(event.get('time','')).strip().lower().replace('.','')
                match = re.fullmatch(r'(\d{1,2})(?::(\d{2}))?\s*(am|pm)?',raw_time)
                if not day or not match:
                    raise ValueError('Unclear callback datetime')
                hour = int(match.group(1))
                minute = int(match.group(2) or 0)
                suffix = match.group(3) or ''
                if suffix:
                    if not 1 <= hour <= 12:
                        raise ValueError('Invalid hour')
                    hour = hour % 12 + (12 if suffix == 'pm' else 0)
                time = datetime.time(hour,minute)
                candidate = datetime.datetime.combine(day,time).replace(tzinfo=now.tzinfo)
                valid = day in [today,next_day] and datetime.time(10,0) <= time <= datetime.time(19,0) and candidate > now
                if not valid:
                    raise ValueError('Outside callback window')
                vars['callback_date'] = day.isoformat()
                vars['callback_time'] = time.strftime('%H:%M')
                vars['callback_state'] = 'valid'
                vars['identity_instruction'] = 'State the validated callback date and time, then immediately call schedule_callback with those exact values.'
            except Exception:
                count = int(vars.get('callback_invalid_count',0)) + 1
                vars['callback_invalid_count'] = count
                vars['callback_state'] = 'exhausted' if count >= 2 else 'invalid'
                vars['identity_instruction'] = 'Explain the permitted window and ask once for another date and time.' if count < 2 else 'No callback can be scheduled. Finish not_reached/no_callback.'
                if count >= 2:
                    vars['identity_exit_reason'] = 'no_callback'
                    vars['identity_finish'] = 'yes'
                    vars['validation_route'] = 'reconcile'
        else:
            vars['identity_instruction'] = 'Continue the current identity question; do not make a bank call without a complete customer answer.'
    else:
        items = decoded(vars.get('work_items',[]),[])
        event = decoded(vars.get('payment_event',''),dict())
        vars['payment_event'] = ''
        kind = str(event.get('kind','clarify'))
        scope = str(event.get('scope','current'))
        amount_raw = event.get('amount','')
        date_raw = str(event.get('date','')).strip()
        messages = []
        def offer(item):
            if vars.get('hardship_active') == 'yes':
                messages.append('Offer support without persuasion; a voluntary proposal is still possible.')
                return
            if item.get('offer_date','') != '':
                rejected = item.setdefault('rejected',[])
                pair = [item.get('offer_amount',''),item.get('offer_date','')]
                if pair not in rejected:
                    rejected.append(pair)
            attempts = int(item.get('attempts',0))
            maximum = int(item.get('max_attempts',1))
            if attempts >= maximum:
                item['status'] = 'refused'
                return
            number = attempts + 1
            day = item.get('attempt1_date','') if number == 1 else item['deadline']
            amount = item['floor'] if number == 2 or item.get('full_too_much') == 'yes' else item['full']
            if not day or datetime.date.fromisoformat(day) < today:
                messages.append('The source supplies no permissible attempt-1 date for this call day. Do not invent an offer; explain that you cannot offer that past date. A voluntary valid proposal remains possible.')
                return
            if [amount,day] in item.get('rejected',[]):
                item['status'] = 'refused'
                return
            item['attempts'] = number
            item['offer_amount'] = amount
            item['offer_date'] = day
            item['offer_kind'] = 'persuasion'
            messages.append('Offer ' + item['label'] + ': ' + str(amount) + ' on ' + day + '. Persuasion offer ' + str(number) + ' of ' + str(maximum) + '.')
        def floor_offer(item):
            item['full_too_much'] = 'yes'
            if item.get('floor_offered') == 'yes':
                offer(item)
                return
            item['floor_offered'] = 'yes'
            item['offer_amount'] = item['floor']
            day = item.get('offer_date','') or item.get('date','')
            item['offer_date'] = day
            item['offer_kind'] = 'floor'
            item['status'] = 'open'
            messages.append('Offer the floor ' + str(item['floor']) + ' for ' + item['label'] + (' on ' + day if day else '') + ' once. Say the rest remains overdue. Obtain acceptance; do not silently replace the customer amount.')
        unresolved = [p for p in items if p.get('status') in ['open','pending']]
        target_id = str(event.get('product_id','')) or str(vars.get('active_product_id',''))
        targets = unresolved if scope == 'all' or kind in ['all_today_yes','stop'] else [p for p in unresolved if p['product_id'] == target_id]
        if kind == 'confirm':
            if items and not any(p.get('status') == 'open' for p in items) and any(p.get('status') == 'pending' for p in items):
                confirmed = [dict(product_id=p['product_id'],amount=p['amount'],date=p['date']) for p in items if p.get('status') == 'pending']
                vars['confirmed_items'] = confirmed
                vars['confirmation_status'] = 'confirmed'
                vars['validation_route'] = 'confirm'
                messages.append('The exact combined read-back is confirmed. Immediately write the first confirmed unrecorded promise, then follow each result.')
            else:
                messages.append('There is no complete valid read-back to confirm. Resolve the missing product facts first.')
        else:
            vars['confirmation_status'] = 'waiting'
            vars['confirmed_items'] = []
            if kind == 'hardship':
                vars['hardship_active'] = 'yes'
                messages.append('Say one short sentence of sympathy. Make no persuasion attempt. Offer connection to support unless the customer is making a voluntary proposal now.')
                if amount_raw != '' or date_raw:
                    kind = 'proposal'
            if kind in ['all_today_no','refusal','non_answer']:
                for item in targets[:1] if kind == 'all_today_no' else targets:
                    item['status'] = 'open'
                    offer(item)
            elif kind == 'too_much':
                for item in targets:
                    floor_offer(item)
            elif kind in ['paid','dispute','decline_support','stop']:
                if kind == 'decline_support' and scope != 'current':
                    targets = unresolved
                status = 'hardship' if kind == 'decline_support' else 'refused' if kind == 'stop' else kind
                for item in targets:
                    item['status'] = status
                if kind == 'paid':
                    messages.append('Say payments can take one business day to appear. Continue with the other products; do not write notes yet.')
            elif kind in ['proposal','correction','all_today_yes','accept_offer','vague']:
                if not targets:
                    messages.append('Clarify which unrecorded product the customer means. Recorded promises cannot be changed; direct changes to the mobile app.')
                for item in targets:
                    item['status'] = 'open'
                    if kind == 'all_today_yes':
                        amount = item['full']
                        raw_day = 'today'
                    elif kind == 'accept_offer':
                        amount = item.get('offer_amount','')
                        raw_day = item.get('offer_date','')
                    else:
                        amount = amount_raw if amount_raw != '' else item.get('amount','')
                        if amount == '':
                            amount = item.get('offer_amount','')
                        if amount == '':
                            amount = item['floor'] if item.get('full_too_much') == 'yes' else item['full']
                        raw_day = date_raw or item.get('date','')
                    try:
                        normalized = str(amount).strip().replace(',','')
                        if not re.fullmatch(r'\d+(?:\.\d+)?',normalized):
                            raise ValueError('Amount representation')
                        number = float(normalized)
                    except Exception:
                        messages.append('Clarify the representation of the amount already proposed; do not ask how much they can pay.')
                        continue
                    if number < item['floor']:
                        floor_offer(item)
                        continue
                    if number > item['full']:
                        item['offer_amount'] = item['full']
                        item['offer_date'] = raw_day if re.fullmatch(r'\d{4}-\d{2}-\d{2}',str(raw_day)) else ''
                        item['offer_kind'] = 'amount_limit'
                        messages.append('Explain that the recordable full past-due amount is ' + str(item['full']) + ' and offer it. Obtain confirmation; do not silently reduce the amount.')
                        continue
                    item['amount'] = number
                    try:
                        day = parse_day(raw_day)
                    except Exception:
                        day = False
                    if not day:
                        if raw_day or kind == 'vague':
                            item['vague_count'] = int(item.get('vague_count',0)) + 1
                        if int(item.get('vague_count',0)) >= 2:
                            day = datetime.date.fromisoformat(item['deadline'])
                            messages.append('The date remains vague after one clarification. Propose the deadline for ' + item['label'] + '.')
                        else:
                            messages.append('Ask for the exact payment day for ' + item['label'] + ' at the accepted amount ' + str(number) + '.')
                            continue
                    deadline = datetime.date.fromisoformat(item['deadline'])
                    if day < today:
                        messages.append('Explain that a past payment date cannot be recorded. Ask for a date from today through ' + item['deadline'] + '; do not infer a different year.')
                        continue
                    if day > deadline:
                        day = deadline
                        messages.append(('For the shared date, ' if scope == 'all' else 'Explain the latest date you can record; offer ') + item['label'] + ' on its deadline ' + item['deadline'] + '. Disclose this adjustment in the read-back.')
                    elif not business(day):
                        day = next_business(day)
                        if day > deadline:
                            day = deadline
                        messages.append('The proposed day is not a business day. Offer ' + day.isoformat() + ' for ' + item['label'] + ' and include the alternative in the read-back.')
                    item['date'] = day.isoformat()
                    item['status'] = 'pending'
                    item['offer_amount'] = number
                    item['offer_date'] = day.isoformat()
            elif kind == 'clarify':
                messages.append('Ask only for the missing clarification of the current question. Do not treat unrelated events as payment proposals.')
            open_items = [p for p in items if p.get('status') == 'open']
            if open_items:
                current = open_items[0]
                previous_id = str(vars.get('active_product_id',''))
                vars['active_product_id'] = current['product_id']
                if current['product_id'] != previous_id and int(current.get('attempts',0)) == 0 and vars.get('hardship_active') != 'yes':
                    offer(current)
                vars['validation_route'] = 'collection'
            elif any(p.get('status') == 'pending' for p in items):
                vars['validation_route'] = 'confirm'
                messages.append('Read ALL pending product labels, amounts and dates together, including adjustments, and ask Do you confirm? Wait for a clear yes.')
            elif items:
                vars['validation_route'] = 'reconcile'
        vars['work_items'] = items
        vars['product_facts'] = json.dumps(items)
        vars['validation_message'] = ' '.join(messages) or 'Continue the current permitted question immediately.'
except Exception:
    vars['validation_route'] = 'collection' if vars.get('security_route') == 'verified' else 'identity'
    vars['validation_message'] = 'The latest input could not be validated. Ask only for the missing or corrected information. Make no bank write.'
    vars['identity_instruction'] = 'The input could not be validated. Ask only for the missing or corrected information; do not submit a partial security answer.'
    vars['security_input_state'] = 'missing'
    vars['confirmation_status'] = 'waiting'
    vars['confirmed_items'] = []

