import json
try:
    def read(value):
        if isinstance(value,str):
            try:
                value = json.loads(value)
            except Exception:
                value = []
        return value if isinstance(value,list) else []
    vars['finish_mode'] = 'hold'
    vars['finish_instruction'] = 'The available bank response does not support a completed outcome. Explain the service problem without claiming success. Do not invent an outcome or retry budget.'
    vars['close_outcome'] = ''
    vars['close_reason'] = ''
    vars['notes_due'] = []
    records = read(vars.get('recorded_promises',[]))
    notes = read(vars.get('successful_notes',[]))
    items = read(vars.get('work_items',[]))
    transfer = vars.get('transfer_status','none')
    if vars.get('close_attempted') == 'yes':
        vars['finish_instruction'] = 'A close was already attempted. Make no further bank call. If it failed, explain that it could not be completed; do not falsely hang up as successfully closed.'
    elif transfer == 'succeeded':
        vars['close_outcome'] = 'transferred'
        vars['close_reason'] = str(vars.get('transfer_reason',''))
        vars['finish_mode'] = 'close'
        vars['finish_instruction'] = 'Confirm the successful transfer without revealing unverified account information. Preserve actual promises and give their required text-message notification if applicable. Add no notes. Thank the customer, say goodbye, then call close_call once.'
    elif transfer in ['requested','failed']:
        vars['finish_instruction'] = 'The transfer has not succeeded. Do not claim a transfer, record pending promises or add notes. Explain the service problem. No failure outcome or further retry budget is specified.'
    elif vars.get('security_route') != 'verified':
        reason = str(vars.get('identity_exit_reason',''))
        if reason in ['failed','declined']:
            vars['close_outcome'] = 'not_verified'
            vars['close_reason'] = reason
            vars['finish_mode'] = 'close'
        elif reason in ['callback','no_callback','wrong_number','deceased','unclear']:
            vars['close_outcome'] = 'not_reached'
            vars['close_reason'] = reason
            vars['finish_mode'] = 'close'
        if vars['finish_mode'] == 'close':
            vars['finish_instruction'] = 'Use the established identity outcome. For failed security direct the customer to the mobile app or a branch; for deceased give condolences only if not already said. Confirm a callback only if it succeeded. Disclose no account information. Thank the speaker, say goodbye, then call close_call once.'
    elif items and not any(p.get('status') in ['open','pending'] for p in items):
        recorded_ids = [p.get('product_id') for p in records]
        note_ids = [p.get('product_id') for p in notes]
        unresolved_notes = []
        valid = True
        for item in items:
            if item['product_id'] not in recorded_ids:
                reason = item.get('status','')
                if reason not in ['refused','hardship','dispute','paid','service_error']:
                    valid = False
                elif item['product_id'] not in note_ids:
                    unresolved_notes.append(dict(product_id=item['product_id'],reason=reason))
        if valid:
            if records:
                vars['close_outcome'] = 'promise'
            elif all(p.get('status') == 'paid' for p in items):
                vars['close_outcome'] = 'paid'
            else:
                first = next(p for p in items if p.get('status') != 'paid')
                vars['close_outcome'] = 'no_promise'
                vars['close_reason'] = first['status']
            vars['notes_due'] = unresolved_notes
            vars['finish_mode'] = 'notes' if unresolved_notes else 'close'
            vars['finish_instruction'] = 'The conversation is resolved. If a transfer request is already pending, suspend this batch before any note. Otherwise record each due note once, without asking another question. After all notes succeed, confirm only actual recorded promises, say the required text-message sentence for them, thank the customer and say goodbye before the single close_call.'
except Exception:
    vars['finish_mode'] = 'hold'
    vars['finish_instruction'] = 'Final state could not be reconciled safely. Explain the problem and make no closing or note claim.'
    vars['close_outcome'] = ''
    vars['close_reason'] = ''
    vars['notes_due'] = []

